namespace Org.OpenAPITools.Models;


/// <summary>
/// A chat completion delta generated by streamed model responses.
/// </summary>
public class ChatCompletionStreamResponseDelta 
{
    public string Content { get; set; }
    public ChatCompletionStreamResponseDeltaFunctionCall FunctionCall { get; set; }
    public List<ChatCompletionMessageToolCallChunk> ToolCalls { get; set; }
    
    /// <summary>
    /// The role of the author of this message.
    /// </summary>
    /// <value>The role of the author of this message.</value>
    public enum RoleEnum
    {
        
        /// <summary>
        /// Enum SystemEnum for system
        /// </summary>
        SystemEnum = 1,
        
        /// <summary>
        /// Enum UserEnum for user
        /// </summary>
        UserEnum = 2,
        
        /// <summary>
        /// Enum AssistantEnum for assistant
        /// </summary>
        AssistantEnum = 3,
        
        /// <summary>
        /// Enum ToolEnum for tool
        /// </summary>
        ToolEnum = 4
    }

    public RoleEnum Role { get; set; }
    public string Refusal { get; set; }
}


